}
internal::CDT cdt;
cdt.insert_constraint(polygon1.vertices_begin(), polygon1.vertices_end(), true);
internal::markDomains(cdt);
int solidComponents = 0;
for (internal::CDT::Finite_faces_iterator fit = cdt.finite_faces_begin(); fit != cdt.finite_faces_end(); ++fit) {
    if (fit->info().in_domain()) {
        internal::Triangle triangle = *fit;
        internal::CDT::Vertex_handle v = triangle.vertex(0);
        const internal::CGALPoint p1 = v->point();
        v = triangle.vertex(1);
        const internal::CGALPoint p2 = v->point();
        v = triangle.vertex(2);
        const internal::CGALPoint p3 = v->point();
        double edge1 = std::sqrt(std::pow(p2.x() - p1.x(), 2) + std::pow(p2.y() - p1.y(), 2));
        double edge2 = std::sqrt(std::pow(p3.x() - p2.x(), 2) + std::pow(p3.y() - p2.y(), 2));
        double edge3 = std::sqrt(std::pow(p1.x() - p3.x(), 2) + std::pow(p1.y() - p3.y(), 2));
        if (edge1 <= alpha && edge2 <= alpha && edge3 <= alpha) {
            solidComponents++;
        }
    }
}
return solidComponents;

